using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class BeachShoreSoftening{static BeachShoreSoftening(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachShoreSoftening.request"))return;File.Delete("BeachShoreSoftening.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachShoreSoftening.txt",e.ToString());}}
static void Run(){Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeSoftBeachEdges");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeSoftBeachEdges/Scene.unity",true);var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");int moved=0;foreach(string name in new[]{"Outer_MEsh","Canal1"}){var f=roads.GetComponentsInChildren<MeshFilter>().Single(m=>m.name==name);var old=f.sharedMesh;var m=UnityEngine.Object.Instantiate(old);m.name=name+" smooth shoreline normals and edges";var local=m.vertices;var world=local.Select(f.transform.TransformPoint).ToArray();var map=new Dictionary<string,int>();var points=new List<Vector3>();var groups=new int[world.Length];for(int i=0;i<world.Length;i++){var p=world[i];string key=Mathf.RoundToInt(p.x*100)+","+Mathf.RoundToInt(p.y*100)+","+Mathf.RoundToInt(p.z*100);int index;if(!map.TryGetValue(key,out index)){index=points.Count;map[key]=index;points.Add(p);}groups[i]=index;}var neighbors=points.Select(p=>new HashSet<int>()).ToArray();var ids=m.triangles;for(int i=0;i<ids.Length;i+=3)for(int j=0;j<3;j++){int a=groups[ids[i+j]],b=groups[ids[i+(j+1)%3]];neighbors[a].Add(b);neighbors[b].Add(a);}var pp=points.ToArray();for(int pass=0;pass<3;pass++){var next=(Vector3[])pp.Clone();for(int i=0;i<pp.Length;i++){if(pp[i].y>=27.55f||pp[i].y<21.8f||neighbors[i].Count<2)continue;var avg=Vector3.zero;foreach(int j in neighbors[i])avg+=pp[j];avg/=neighbors[i].Count;var delta=Vector3.ClampMagnitude(new Vector3(avg.x-pp[i].x,0,avg.z-pp[i].z)*.22f,.6f);next[i]+=delta;}pp=next;}for(int i=0;i<world.Length;i++){if(world[i].y<27.55f&&world[i].y>=21.8f){var delta=pp[groups[i]]-points[groups[i]];world[i]+=delta;if(delta.sqrMagnitude>.0001)moved++;}local[i]=f.transform.InverseTransformPoint(world[i]);}m.vertices=local;var normals=new Vector3[points.Count];for(int i=0;i<ids.Length;i+=3){var a=world[ids[i]];var b=world[ids[i+1]];var c=world[ids[i+2]];var n=Vector3.Cross(b-a,c-a);if(n.y<0)n=-n;foreach(int id in new[]{ids[i],ids[i+1],ids[i+2]})normals[groups[id]]+=n;}m.normals=Enumerable.Range(0,world.Length).Select(i=>{var n=normals[groups[i]].normalized;if(world[i].y>=27.7f)n=Vector3.up;else if(world[i].y>27.0f)n=Vector3.Lerp(n,Vector3.up,Mathf.SmoothStep(0,1,(world[i].y-27)/.74f)).normalized;return f.transform.InverseTransformDirection(n);}).ToArray();m.RecalculateBounds();m.RecalculateTangents();string path="Assets/Scenes/Oasis/BeachShoreline/"+name+" Soft Beach Edges.asset";AssetDatabase.CreateAsset(m,path);f.sharedMesh=m;var col=f.GetComponent<MeshCollider>();if(col)col.sharedMesh=m;PrefabUtility.RecordPrefabInstancePropertyModifications(f);var pf=prefab.GetComponentsInChildren<MeshFilter>().Single(v=>v.name==name);pf.sharedMesh=m;if(pf.GetComponent<MeshCollider>())pf.GetComponent<MeshCollider>().sharedMesh=m;}PrefabUtility.SaveAsPrefabAsset(prefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(prefab);var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/BeachShoreline/Beach Shoreline.mat");mat.SetFloat("_WetFade",10);mat.SetFloat("_BlendWidth",1.8f);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/BeachShoreSoftening.txt","SUCCESS softened outer/canal sand shoulder geometry and welded smooth normals; fixed road-height positions; sand slope horizontal smoothing <=1.8m; wider wet-sand blend; original UV/materials retained; changed slope samples="+moved);}}
